P16 = 'phase16_qwen_routing_check'
REPO = 'ASK-memory-governance@f6bf66e'
rows = []
def R(id_, file, loc, claim, v, ev, fix=''):
    rows.append((id_, file, loc, claim, V[v], ev, fix))

